steps.run:
node - <<'JS'
const fs=require('node:fs'), path=require('node:path');
const output=process.env.BROWSER_ARTIFACT_DIR || path.join(process.env.RUNNER_TEMP,'ui-visual',process.env.GITHUB_SHA);
fs.mkdirSync(output,{recursive:true});
const file=path.join(output,'result.json');
if(!fs.existsSync(file)) fs.writeFileSync(file,JSON.stringify({
  head_sha:process.env.GITHUB_SHA,status:'not_completed',
  reason:'A blocking installation, integrity, test or build step did not complete. See logs and job steps.',
  run_url:`https://github.com/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`
},null,2));
JS
